using Spar.Generator;

namespace Spar.Sdk.Tasks.Client;

/// <summary>
/// The <c>.d.ts</c> of each module (<c>docs/app-model.md</c> section 5): DTOs as <c>readonly</c> interfaces, each error
/// type as an interface map from case to payload, and one object per contract with a property per command.
/// </summary>
internal static class DeclarationEmitter
{
    /// <summary>A contract's declarations; the writer also holds their map to the C# (<see cref="TypeScriptWriter.SourceMap"/>).</summary>
    public static TypeScriptWriter Contract(ClientLayout layout, ClientContract contract)
    {
        var ts = new TypeScriptWriter()
            .Line($"// Generated by Spar from {contract.SourceFile}. Do not edit.")
            // By package name, as app code writes it; TypeScript resolves the package's own name through its exports.
            .Line($"import type {{ {string.Join(", ", SdkTypes(contract.Model))} }} from \"@spar/app/sdk\";");

        var imported = layout.Imported(contract).Select(t => t.Name).ToList();
        if (imported.Count > 0)
        {
            var names = string.Join(", ", imported);
            ts.Line($"import type {{ {names} }} from \"./shared.js\";")
                .Line()
                .Line($"export type {{ {names} }} from \"./shared.js\";");
        }

        foreach (var type in layout.Own(contract))
        {
            ts.Line();
            Type(ts, layout, type, contract.Docs);
        }

        ts.Line();
        ContractObject(ts, layout, contract);
        return ts.Line($"//# sourceMappingURL={contract.Model.WireName}.d.ts.map");
    }

    public static TypeScriptWriter Shared(ClientLayout layout)
    {
        var ts = new TypeScriptWriter().Line("// Generated by Spar: the types more than one contract uses. Do not edit.");
        var blobs = layout.Shared.Any(t =>
            t.Record?.Properties.Any(p => NamesBlob(p.Type)) == true
            || t.Error?.Cases.Any(c => c.Properties.Any(p => NamesBlob(p.Type))) == true);
        if (blobs)
        {
            ts.Line("import type { SparBlob } from \"@spar/app/sdk\";");
        }

        var grants = new[] { (WireKind.FileGrant, "PickedFile"), (WireKind.FolderGrant, "PickedFolder") }
            .Where(grant => layout.Shared.Any(t =>
                t.Record?.Properties.Any(p => Names(p.Type, grant.Item1)) == true
                || t.Error?.Cases.Any(c => c.Properties.Any(p => Names(p.Type, grant.Item1))) == true))
            .Select(grant => grant.Item2)
            .ToList();
        if (grants.Count > 0)
        {
            ts.Line($"import type {{ {string.Join(", ", grants)} }} from \"@spar/app/sdk\";");
        }

        foreach (var type in layout.Shared)
        {
            var docs = layout.Contracts.First(c => ClientLayout.Keys(c.Model).Contains(type.Key)).Docs;
            ts.Line();
            Type(ts, layout, type, docs);
        }

        return ts.Line("//# sourceMappingURL=shared.d.ts.map");
    }

    public static string Spar() => new TypeScriptWriter()
        .Line("// Generated by Spar. Do not edit.")
        .Line()
        .Line("/** The contracts' fingerprint this page was built against; the host compares it once, when the page opens. */")
        .Line("export declare const fingerprint: string;")
        .ToString();

    /// <summary>
    /// The page's window module: the SDK's, typed with the window kinds <c>Program.cs</c> declares as a union, so a
    /// misspelled kind fails tsc; <c>never</c> when the app declares none.
    /// </summary>
    /// <summary>
    /// The <c>windows</c> module: the kinds <c>windows.open</c> takes, and those <c>windows.showModal</c> takes (declared
    /// with <c>Modal()</c>). A kind whose options the build could not read is in both; the start checks it.
    /// </summary>
    public static string Windows(IReadOnlyList<WindowKindName>? kinds = null)
    {
        var open = Union(kinds?.Where(kind => kind.Modal != true));
        var modal = Union(kinds?.Where(kind => kind.Modal != false));
        return new TypeScriptWriter()
            .Line("// Generated by Spar: this window, and the window kinds Program.cs declares. Do not edit.")
            .Line("import type { WindowsApi } from \"./sdk/windows.js\";")
            .Line()
            .Line("export type { CloseAnswer, CloseGuard, CloseRequest, ModalError, OpenError, WindowParams, WindowsApi } from \"./sdk/windows.js\";")
            .Line()
            .Line("/** The window kinds Program.cs declares with spar.Window(kind, …) that windows.open opens. */")
            .Line($"export type WindowKind = {open};")
            .Line()
            .Line("/** The window kinds Program.cs declares with Modal(), which windows.showModal shows. */")
            .Line($"export type ModalKind = {modal};")
            .Line()
            .Line("/** This window, and the app's other windows by kind. */")
            .Line("export declare const windows: WindowsApi<WindowKind, ModalKind>;")
            .ToString();

        static string Union(IEnumerable<WindowKindName>? names)
        {
            var list = names?.Select(kind => $"\"{kind.Name}\"").ToList() ?? [];
            return list.Count > 0 ? string.Join(" | ", list) : "never";
        }
    }

    public static string Testing() => new TypeScriptWriter()
        .Line("// Generated by Spar: the fake backend for page tests. Do not edit.")
        .Line("import type { FakeSpar } from \"./sdk/testing.js\";")
        .Line()
        .Line("export type { FakeBackendUpdate, FakeCloseRequest, FakeSpar, Replies, Reply, Script, ScriptedFailure, StreamScript } from \"./sdk/testing.js\";")
        .Line()
        .Line("/**")
        .Line(" * A fake backend for page tests, connected in place of the host; each test makes its own. Script a command with")
        .Line(" * `spar.on(pages.get)`, a stream or subscription with `spar.stream(pages.changes)`, read what the page sent with")
        .Line(" * `spar.calls(pages.get)`. It also resets the failure hooks of")
        .Line(" * `configureSpar`.")
        .Line(" */")
        .Line("export declare function fakeSpar(): FakeSpar;")
        .ToString();

    private static void Type(TypeScriptWriter ts, ClientLayout layout, ClientType type, ClientDocs docs)
    {
        if (type.Enum is { } members)
        {
            // A union of the member names, exactly as C# spells them (wire rules).
            var union = string.Join(" | ", members.Members.Select(TypeScriptNames.Literal));
            ts.Doc(docs.Type(members.CSharp)).Line($"export type {type.Name} = {union};", TypeSpot(docs, members.CSharp), type.Name);
            return;
        }

        if (type.Record is { } record)
        {
            ts.Doc(docs.Type(record.CSharp)).Open($"export interface {type.Name} {{", TypeSpot(docs, record.CSharp), type.Name);
            Properties(ts, layout, record.CSharp, record.Properties, docs);
            ts.Close();
            return;
        }

        var error = type.Error!;
        var cSharpName = $"(C# `{type.Name}`)";
        var summary = docs.Type(error.CSharp);
        ts.Doc(summary is null ? cSharpName : $"{summary} {cSharpName}").Open($"export interface {type.Name} {{", TypeSpot(docs, error.CSharp), type.Name);
        var first = true;
        foreach (var @case in error.Cases)
        {
            if (!first)
            {
                ts.Line();
            }

            first = false;
            ts.Doc(docs.Type(@case.CSharp));
            var caseSpot = TypeSpot(docs, @case.CSharp);
            if (@case.Properties.Length == 0)
            {
                ts.Line($"readonly {Key(@case.Code)}: undefined;", caseSpot, Key(@case.Code));
                continue;
            }

            ts.Open($"readonly {Key(@case.Code)}: {{", caseSpot, Key(@case.Code));
            Properties(ts, layout, @case.CSharp, @case.Properties, docs);
            ts.Close("};");
        }

        ts.Close();
    }

    private static void Properties(TypeScriptWriter ts, ClientLayout layout, string owner, EquatableArray<PropertyModel> properties, ClientDocs docs)
    {
        foreach (var property in properties)
        {
            var spot = docs.ParameterSpot(owner, property.Name, out var found) ? found : (SourceSpot?)null;
            ts.Doc(docs.Parameter(owner, property.Name))
                .Line($"readonly {Key(property.JsonName)}: {TypeOf(layout, property.Type)};", spot, Key(property.JsonName));
        }
    }

    private static void ContractObject(TypeScriptWriter ts, ClientLayout layout, ClientContract contract)
    {
        var model = contract.Model;
        var wireName = $"Wire name: {model.WireName}.";
        var summary = contract.Docs.Type(model.CSharp);
        ts.Doc(summary is null ? wireName : $"{summary} {wireName}")
            .Open($"export declare const {model.WireName}: {{", TypeSpot(contract.Docs, model.CSharp), model.WireName);

        var first = true;
        foreach (var command in model.Commands)
        {
            if (!first)
            {
                ts.Line();
            }

            first = false;
            var parameters = command.Request is null
                ? Options(command)
                : $"{RequestName(command)}: {TypeOf(layout, command.Request)}, {Options(command)}";
            var spot = contract.Docs.MethodSpot(model.CSharp, command.MethodName, out var found) ? found : (SourceSpot?)null;
            if (command.IsResource)
            {
                var request = command.Request is null ? "" : $"{RequestName(command)}: {TypeOf(layout, command.Request)}";
                ts.Doc(contract.Docs.Method(model.CSharp, command.MethodName))
                    .Line($"readonly {Key(command.WireName)}: {{ readonly url: ({request}) => string }};", spot, Key(command.WireName));
                continue;
            }

            ts.Doc(contract.Docs.Method(model.CSharp, command.MethodName))
                .Line($"readonly {Key(command.WireName)}: ({parameters}) => {CallType(layout, command)};", spot, Key(command.WireName));
        }

        ts.Close("};");
    }

    private static SourceSpot? TypeSpot(ClientDocs docs, string csharp) => docs.TypeSpot(csharp, out var spot) ? spot : null;

    /// <summary>A record request is <c>request</c>, as in the app model; a scalar keeps its C# parameter name.</summary>
    public static string RequestName(CommandModel command) =>
        command.Request?.Kind == WireKind.Record ? "request" : TypeScriptNames.Parameter(command.RequestName ?? "request");

    /// <summary>
    /// The SDK types a module's declarations name, in alphabetical order: <c>Call</c> and <c>CallOptions</c> for calls
    /// (and in a module without streams, as before streams existed), <c>Result</c> for streams, and the subscription types.
    /// </summary>
    private static IEnumerable<string> SdkTypes(ContractModel model)
    {
        var calls = model.Commands.Any(c => !c.IsStream && !c.IsResource) || !model.Commands.Any(c => c.IsStream);
        var streams = model.Commands.Any(c => c.IsStream && c.Subscription is null);
        var subscriptions = model.Commands.Any(c => c.Subscription is not null);
        if (calls)
        {
            yield return "Call";
        }

        if (calls || streams || subscriptions)
        {
            yield return "CallOptions";
        }

        if (model.Commands.Any(c => c.Subscription is { LatestOnly: true }))
        {
            yield return "LatestOnlyEvents";
        }

        if (streams)
        {
            yield return "Result";
        }

        if (model.Types.Any(t => t.Kind == WireKind.Blob))
        {
            yield return "SparBlob";
        }

        if (model.Types.Any(t => t.Kind == WireKind.FileGrant))
        {
            yield return "PickedFile";
        }

        if (model.Types.Any(t => t.Kind == WireKind.FolderGrant))
        {
            yield return "PickedFolder";
        }

        if (subscriptions)
        {
            yield return "SubscribeOptions";
            yield return "Subscription";
        }
    }

    /// <summary>Whether a property's TypeScript spelling names <c>SparBlob</c>: a blob, or a list or nullable of one.</summary>
    private static bool NamesBlob(TypeRef type) => type.Kind switch
    {
        WireKind.Blob => true,
        WireKind.List or WireKind.Nullable => NamesBlob(type.Element!),
        _ => false,
    };

    /// <summary>Whether a property's TypeScript spelling names the type of <paramref name="kind"/>, itself or in a list or nullable.</summary>
    private static bool Names(TypeRef type, WireKind kind) =>
        type.Kind == kind || (type.Kind is WireKind.List or WireKind.Nullable && Names(type.Element!, kind));

    private static string Options(CommandModel command) => command.Subscription is { } subscription
        ? $"options?: SubscribeOptions<\"{(subscription.Automatic ? "automatic" : "manual")}\">"
        : "options?: CallOptions";

    /// <summary>
    /// A call is <c>Call&lt;T, E&gt;</c>, a one-shot stream an <c>AsyncIterable</c> of <c>Result&lt;T, E&gt;</c>, and a
    /// subscription <c>Subscription&lt;T, E&gt;</c>, with <c>LatestOnlyEvents</c> when it keeps only its newest value.
    /// </summary>
    private static string CallType(ClientLayout layout, CommandModel command)
    {
        var value = command.Value is null ? "void" : TypeOf(layout, command.Value);
        var error = command.ErrorKey is null ? null : layout.Type(command.ErrorKey).Name;
        if (command.Subscription is { } subscription)
        {
            var errors = error ?? "{}";
            return subscription.LatestOnly ? $"Subscription<{value}, {errors}, LatestOnlyEvents>"
                : error is null ? $"Subscription<{value}>"
                : $"Subscription<{value}, {error}>";
        }

        if (command.IsStream)
        {
            return error is null ? $"AsyncIterable<Result<{value}>>" : $"AsyncIterable<Result<{value}, {error}>>";
        }

        return error is null ? $"Call<{value}>" : $"Call<{value}, {error}>";
    }

    /// <summary>The TypeScript spelling of a wire type (plan section 2, the wire-rules table).</summary>
    public static string TypeOf(ClientLayout layout, TypeRef type) => type.Kind switch
    {
        WireKind.String or WireKind.Decimal or WireKind.Char or WireKind.Guid or WireKind.DateTime or WireKind.DateTimeOffset
            or WireKind.DateOnly or WireKind.TimeOnly or WireKind.TimeSpan => "string",
        WireKind.Boolean => "boolean",
        WireKind.Byte or WireKind.SByte or WireKind.Int16 or WireKind.UInt16 or WireKind.Int32 or WireKind.UInt32
            or WireKind.Single or WireKind.Double => "number",
        WireKind.Int64 or WireKind.UInt64 => "bigint",
        WireKind.Bytes => "Uint8Array",
        WireKind.Blob => "SparBlob",
        WireKind.FileGrant => "PickedFile",
        WireKind.FolderGrant => "PickedFolder",
        WireKind.List => $"readonly {Parenthesized(TypeOf(layout, type.Element!))}[]",
        WireKind.Nullable => $"{TypeOf(layout, type.Element!)} | null",
        WireKind.Enum => layout.Type(type.Key).Name,
        WireKind.Record => layout.Type(type.Key).Name,
        _ => throw new InvalidOperationException($"No TypeScript spelling for wire kind {type.Kind}."),
    };

    /// <summary>A property name as written in an interface: plain when it is an identifier, quoted otherwise.</summary>
    public static string Key(string name) => ModuleEmitter.IsIdentifier(name) ? name : TypeScriptNames.Literal(name);

    private static string Parenthesized(string type) => type.Contains(' ', StringComparison.Ordinal) ? $"({type})" : type;
}
